import NoDataYetIcon from 'assets/NoDataYet.svg';
import SearchEmptyIcon from 'assets/Search-Empty.svg';
import ComingSoonIcon from 'assets/training-coming-soon.svg';

import { EmptyProps } from '../../domain';
import {
  StyledEmptyContainer,
  StyledEmptyDescription,
  StyledEmptyIcon,
  StyledEmptyTitle,
} from './Empty.styles';

export const Empty = ({ title, description, type }: EmptyProps) => {
  const getIcon = () => {
    if (!type) return null;
    switch (type) {
      case 'coming-soon':
        return (
          <StyledEmptyIcon
            src={ComingSoonIcon}
            alt="Coming Soon"
            $type={type}
          />
        );
      case 'no-data':
        return (
          <StyledEmptyIcon src={NoDataYetIcon} alt="No Data" $type={type} />
        );
      case 'search-empty':
        return (
          <StyledEmptyIcon
            src={SearchEmptyIcon}
            alt="Search Empty"
            $type={type}
          />
        );
      default:
        return null;
    }
  };

  return (
    <StyledEmptyContainer $type={type}>
      {getIcon()}
      <StyledEmptyTitle $hasData={!!title}>{title}</StyledEmptyTitle>
      <StyledEmptyDescription $type={type} $hasData={!!description}>
        {description}
      </StyledEmptyDescription>
    </StyledEmptyContainer>
  );
};
